import{_ as e,o as a,c as r,ai as i}from"./chunks/framework.DQi1ytmF.js";const m=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"resources/examples.md","filePath":"resources/examples.md"}'),o={name:"resources/examples.md"};function s(n,t,c,d,l,p){return a(),r("div",null,[...t[0]||(t[0]=[i('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/resources/examples.md for this page in Markdown format</div><h1 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h1><p>Every example below is a real route of one of the demo applications. Each opens in StackBlitz on the relevant file, already navigated to the page.</p><p>The demo groups them the way you would meet them: <strong>components</strong> first, then the <strong>primitives</strong> on their own, then the same features <strong>behind services</strong>, then <strong>routing</strong> and the rest.</p><div class="tip custom-block"><p class="custom-block-title">Just want to poke at something?</p><p>The <a href="#playground">Playground</a> is a shareable sandbox with a small todo flow — the fastest way to try an idea.</p></div><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><p>Functional, selectorless components rendered from typed hyperscript.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/component/component-demo.ts&amp;initialpath=/" target="_blank" rel="noreferrer">Functional Components</a></td><td><code>craftComponent</code>, inputs and outputs as factory parameters, hyperscript templates</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/component/component-composition-demo.ts&amp;initialpath=/component-composition" target="_blank" rel="noreferrer">Reactive Composition</a></td><td>Composing components and directives with <code>.pipe(...)</code></td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/component/content-projection-demo.ts&amp;initialpath=/content-projection" target="_blank" rel="noreferrer">Content Projection</a></td><td>Free DOM content, typed DOM contracts, and logical projection by contract</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/component/pending-node-demo.ts&amp;initialpath=/pending-node" target="_blank" rel="noreferrer">Pending Block</a></td><td>Type-safe async suspension with <code>settledValue</code>, <code>settled(...)</code> and <code>pendingNode</code></td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/component/pending-node-exception-demo.ts&amp;initialpath=/pending-node/exception" target="_blank" rel="noreferrer">Pending Block — Exception</a></td><td>Coordinating pending, reloading and business-exception fallbacks with <code>pendingNode</code> and <code>catchNode</code></td></tr></tbody></table><h2 id="primitives" tabindex="-1">Primitives <a class="header-anchor" href="#primitives" aria-label="Permalink to &quot;Primitives&quot;">​</a></h2><p>Using <code>state</code>, <code>query</code>, <code>mutation</code>, <code>queryParams</code> and <code>asyncProcess</code> directly, with no service layer.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/query/query.ts&amp;initialpath=/query/1" target="_blank" rel="noreferrer">Query</a></td><td><code>query()</code> with reactive params, status and caching</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/mutation/mutation.ts&amp;initialpath=/mutation/1" target="_blank" rel="noreferrer">Mutation</a></td><td><code>mutation()</code> with manual control of modification operations</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/list-with-pagination/list-with-pagination.ts&amp;initialpath=/list-with-pagination" target="_blank" rel="noreferrer">List with Pagination</a></td><td>Pagination with hand-managed query params and page state</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/granular-mutation/granular-mutation.ts&amp;initialpath=/granular-mutation" target="_blank" rel="noreferrer">Granular Mutation</a></td><td>Optimistic updates and cache invalidation, done by hand</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/full-demo/full-demo.ts&amp;initialpath=/full-demo" target="_blank" rel="noreferrer">Full Demo</a></td><td>Everything at once, without store or service abstractions</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/forms/login-form.ts&amp;initialpath=/login-form" target="_blank" rel="noreferrer">Login Form</a></td><td><code>insertForm</code>, validators, and a typed submit wired to a mutation</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/pixel-art/pixel-art.ts&amp;initialpath=/pixel-art" target="_blank" rel="noreferrer">Pixel Art</a></td><td><code>state</code> + <code>insertSelect</code> over a flat array</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/pixel-art-matrix/pixel-art-matrix.ts&amp;initialpath=/pixel-art-matrix" target="_blank" rel="noreferrer">Pixel Art Matrix</a></td><td>Nested <code>insertSelect</code> and internal <code>source$</code> between rows and cells</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/exceptions/exceptions.ts&amp;initialpath=/exceptions" target="_blank" rel="noreferrer">Exceptions</a></td><td>Business exceptions on <code>query()</code>, rendered per code with <code>matchNode.exhaustive</code></td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/primitives/exceptions/exception-query-params.ts&amp;initialpath=/exception-query-params" target="_blank" rel="noreferrer">Exception QueryParams</a></td><td><code>queryParams</code> decode failures through <code>hasException()</code> and <code>exceptions().parse</code></td></tr></tbody></table><h2 id="services" tabindex="-1">Services <a class="header-anchor" href="#services" aria-label="Permalink to &quot;Services&quot;">​</a></h2><p>The same features, packaged behind <code>craftService</code>.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/query/query.ts&amp;initialpath=/craft/query/1" target="_blank" rel="noreferrer">Craft Query</a></td><td>A reusable query service with configured storage persistence (localStorage by default)</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/mutation/mutation.ts&amp;initialpath=/craft/mutation/1" target="_blank" rel="noreferrer">Craft Mutation</a></td><td>Create / update / delete with reactive cache synchronisation</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/list-with-pagination/list-with-pagination.ts&amp;initialpath=/craft/list-with-pagination" target="_blank" rel="noreferrer">Craft List Pagination</a></td><td><code>queryParams</code> + <code>insertPaginationPlaceholderData</code> in a service</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/granular-mutation/granular-mutation.ts&amp;initialpath=/craft/granular-mutation" target="_blank" rel="noreferrer">Craft Granular Mutation</a></td><td><code>insertReactOnMutation</code> updating cached data without a reload</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/full-demo/full-demo.ts&amp;initialpath=/craft/full-demo" target="_blank" rel="noreferrer">Craft Full Demo</a></td><td>Queries, mutations, async work, URL state and persistence together</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft-service/craft-service-counter.ts&amp;initialpath=/craft-service/counter" target="_blank" rel="noreferrer">craftService Counter</a></td><td>The smallest possible service — scopes and composition</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft-service/craft-service-user-detail.ts&amp;initialpath=/craft-service/user-detail" target="_blank" rel="noreferrer">craftService User Detail</a></td><td>Service inputs, and exposing only part of a dependency</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft-service/register-for.ts&amp;initialpath=/craft-service/register-for" target="_blank" rel="noreferrer">craftRegisterFor</a></td><td>A parent driving live children through a typed registry</td></tr></tbody></table><h2 id="effect" tabindex="-1">Effect <a class="header-anchor" href="#effect" aria-label="Permalink to &quot;Effect&quot;">​</a></h2><p>Concrete EffectTS integration examples, using the dedicated Effect demo.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-demo-effect/tree/main/?file=src/app/examples/effect/effect-profile-lookup.ts&amp;initialpath=/" target="_blank" rel="noreferrer">Profile Lookup</a></td><td><code>queryEffect</code>, typed business errors, and pending / exception rendering</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-demo-effect/tree/main/?file=src/app/examples/effect/effect-access-check-shared-service.ts&amp;initialpath=/access" target="_blank" rel="noreferrer">Access Check</a></td><td>An Effect service provided by the application Layer</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-demo-effect/tree/main/?file=src/app/examples/effect/effect-team-overview-layer-scope.ts&amp;initialpath=/team" target="_blank" rel="noreferrer">Team Overview</a></td><td>Combining application-wide and route-scoped Effect Layers</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-demo-effect/tree/main/?file=src/app/examples/effect/effect-playground.ts&amp;initialpath=/playground" target="_blank" rel="noreferrer">Effect Playground</a></td><td>A shareable todo sandbox with <code>queryEffect</code>, <code>mutationEffect</code>, and a route-provided Effect service</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-demo-effect/tree/main/?file=src/app/shared/i18n-domain.ts&amp;initialpath=/i18n" target="_blank" rel="noreferrer">Translate in an Effect</a></td><td><code>provideI18nRuntime</code> as a route Layer, <code>translateEffect</code> inside a plain Effect program, and the locale as Craft state driving the query params</td></tr></tbody></table><h2 id="design-system" tabindex="-1">Design system <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design system&quot;">​</a></h2><p>The typed style system, at all three of its levels. Both routes read from the same sheets under <code>src/app/examples/design-system/</code>, which has a README walking through the same progression in code.</p><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/design-system/foundation.style.ts&amp;initialpath=/design-system" target="_blank" rel="noreferrer">Mini Design System</a></td><td><code>definePalette</code>, <code>defineStateAxis</code>, <code>cssVars</code> and the theme: one dark-mode rule for the whole system, and variants as <code>data-*</code> attributes rather than class strings</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/design-system/scroll.style.ts&amp;initialpath=/design-system/scroll" target="_blank" rel="noreferrer">Scroll context</a></td><td>Level 3: <code>requires(scrollPort.block)</code> travelling up the tree, <code>provides(...)</code> on the layout that owns the area, and the <code>scrollState</code> axis</td></tr></tbody></table><p>Start from <a href="/craft/guide/style/setup.html">Activating the style system</a> — the sheets emit nothing without the Vite plugin.</p><h2 id="internationalisation" tabindex="-1">Internationalisation <a class="header-anchor" href="#internationalisation" aria-label="Permalink to &quot;Internationalisation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/i18n/i18n.service.ts&amp;initialpath=/i18n" target="_blank" rel="noreferrer">Type-safe i18n</a></td><td><code>defineCatalog</code> + <code>msg</code> + <code>plural</code>, a second locale through <code>defineLocaleLike</code>, every shipped semantic token, a custom <code>defineToken</code>, and <code>runtime.bind</code> switching the whole page reactively</td></tr></tbody></table><p>The guide is <a href="/craft/guide/i18n/">Type-safe i18n</a>.</p><h2 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/routes/list-with-pagination/qp-list-with-pagination.ts&amp;initialpath=/query-params" target="_blank" rel="noreferrer">Query Params in the route</a></td><td><code>queryParams</code> declared on the route rather than in a component</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/routes/guard-demo/GuardDemo.ts&amp;initialpath=/guard-demo" target="_blank" rel="noreferrer">Guard Demo</a></td><td>Guards as bare generators, and <code>handleExceptions</code> per code</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/routes/slow-page/slow-page.routes.ts&amp;initialpath=/slow-page" target="_blank" rel="noreferrer">Slow Page</a></td><td>Non-blocking navigation: the stay → blank → loader phases, and a <code>craftGen</code> resolver recovered locally with <code>catchTag</code></td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/routes/view-transitions/view-transitions.routes.ts&amp;initialpath=/view-transitions" target="_blank" rel="noreferrer">View Transitions</a></td><td>Outlet-driven view transitions surviving the guard/resolve chain, with a per-route skeleton</td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/craft/lazy-layout/lazy-layout.routes.ts&amp;initialpath=/craft/lazy-layout/1" target="_blank" rel="noreferrer">Lazy Layout</a></td><td>A lazy child collection with its own DI check and a route-provided service</td></tr></tbody></table><h2 id="tooling" tabindex="-1">Tooling <a class="header-anchor" href="#tooling" aria-label="Permalink to &quot;Tooling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>What it shows</th></tr></thead><tbody><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/playground/playground.ts&amp;initialpath=/playground" target="_blank" rel="noreferrer">Playground</a></td><td>A shareable sandbox: a small todo flow with <code>craftService</code>, <code>query()</code> and <code>mutation()</code></td></tr><tr><td><a href="https://stackblitz.com/github/craft-ts/craft-ts-demo/tree/main/?file=src/app/examples/ia/demo-send-context/demo-send-context.ts&amp;initialpath=/demo-send-context" target="_blank" rel="noreferrer">Send Context to AI</a></td><td>Exporting the live dependency graph and app context to an assistant</td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Each example ships its own <code>api.service.ts</code> simulating the network, so every route works standalone.</p><p>Source repository: <a href="https://github.com/craft-ts/craft-ts-demo" target="_blank" rel="noreferrer">craft-ts-demo</a>.</p><p>Effect demo source repository: <a href="https://github.com/craft-ts/craft-demo-effect" target="_blank" rel="noreferrer">craft-demo-effect</a>.</p>',32)])])}const f=e(o,[["render",s]]);export{m as __pageData,f as default};
